// Flatten DocuVision result.view.fields (a dict: field name -> scalar | list) into
// one row per field for CSV output. Never invents values.
// Sources (branch feat/r003-p042-egress, 2026-11-15):
//   view["fields"] = kie_fields            backend/app/orchestration/steps/envelope.py:151,153
//   scalar keys backfilled "", list keys   backend/app/services/kie/field_merge.py (backfill_schema_keys)
//   merged into result for GET result      backend/app/orchestration/steps/governance.py:95-99
const taskId = $('Map Callback Payload').first().json.task_id;
const fileName = $('Map Callback Payload').first().json.file_name;
const result = $json;
const view = result && typeof result === 'object' ? result.view : undefined;
const fields = view && typeof view === 'object' ? view.fields : undefined;

if (!fields || typeof fields !== 'object') {
  // KIE off or non-KIE document: emit an observable marker row instead of nothing.
  return [{ json: { task_id: taskId, file_name: fileName, field: '__no_kie_fields__', value: '' } }];
}

const rows = [];
for (const [name, value] of Object.entries(fields)) {
  let v;
  if (value === null || value === undefined) v = '';
  else if (['string', 'number', 'boolean'].includes(typeof value)) v = String(value);
  else v = JSON.stringify(value); // lists (items/line_items/findings) and objects
  rows.push({ json: { task_id: taskId, file_name: fileName, field: name, value: v } });
}
return rows.length ? rows : [{ json: { task_id: taskId, file_name: fileName, field: '__no_kie_fields__', value: '' } }];
